<script setup>
import {ref} from 'vue'
const props=defineProps({level:{default:1},interactive:Boolean})
const selected=ref('');const selectedId=ref('')
const nodes=[{id:'parent',x:70,y:175,label:'Tested parent',detail:'Both proposals start from the same reviewed source and active configuration.'},{id:'a',x:270,y:80,label:'Candidate A',detail:'A proposed edit to model, loss, or training code. A rationale is a hypothesis, not a measured improvement.'},{id:'b',x:270,y:275,label:'Candidate B',detail:'A competing edit from the same parent. It receives its own source fingerprint and training execution.'},{id:'pa',x:465,y:80,label:'Train + validate A',detail:'Train candidate A on training dates. Score predictions on validation dates. Save source, weights, losses, and predictions.'},{id:'pb',x:465,y:275,label:'Train + validate B',detail:'Use the same data partitions and training configuration for candidate B. Retain errors and missing output.'},{id:'compose',x:665,y:175,label:'Compose',detail:'Review both probes and propose selected, combined, or unchanged code. Reviewing a candidate does not imply adopting it.'},{id:'test',x:865,y:175,label:'Test composition',detail:'Execute the exact proposed source. Retain the parent when validation error does not improve.'},{id:'next',x:1050,y:175,label:'Round 2',detail:'Use the adopted code and the saved lesson as the next round’s starting point. The task and scoring rules stay fixed.'}]
const visible=n=>n.id==='parent'||(props.level>=1&&['a','b'].includes(n.id))||(props.level>=2&&['pa','pb'].includes(n.id))||(props.level>=3&&n.id==='compose')||(props.level>=4&&n.id==='test')||(props.level>=5&&n.id==='next')
const choose=n=>{if(props.interactive){selected.value=n.detail;selectedId.value=n.id}}
</script>
<template><div class="research-branches"><svg viewBox="0 0 1140 375" :role="interactive?'group':'img'" aria-label="Two proposed code changes train independently, composition reviews their evidence, the composition runs, and a retained version begins round two">
<g fill="none" stroke-width="3"><path v-if="level>=1" d="M70 175C150 175 150 80 270 80" stroke="#4382a6"/><path v-if="level>=1" d="M70 175C150 175 150 275 270 275" stroke="#c17b40"/><path v-if="level>=2" d="M270 80H465" stroke="#4382a6"/><path v-if="level>=2" d="M270 275H465" stroke="#c17b40"/><path v-if="level>=3" d="M465 80C570 80 565 175 665 175M465 275C570 275 565 175 665 175" stroke="#638382" stroke-dasharray="7 6"/><path v-if="level>=4" d="M665 175H865" stroke="#163c43"/><path v-if="level>=5" d="M865 175H1050" stroke="#163c43"/></g>
<g v-for="n in nodes.filter(visible)" :key="n.id" class="node" :tabindex="interactive?0:-1" :role="interactive?'button':undefined" :aria-label="n.label" :aria-pressed="interactive?selectedId===n.id:undefined" @click="choose(n)" @keydown.enter="choose(n)" @keydown.space.prevent="choose(n)"><rect :x="n.x-90" :y="n.y-20" width="180" height="90" fill="transparent" pointer-events="all"/><circle :cx="n.x" :cy="n.y" r="15" :stroke="selectedId===n.id?'#f1ca70':'none'" stroke-width="5" :fill="['a','pa'].includes(n.id)?'#4382a6':['b','pb'].includes(n.id)?'#c17b40':n.id==='compose'?'#f1ca70':'#163c43'"/><text :x="n.x" :y="n.y+48" text-anchor="middle">{{n.label}}</text><text v-if="n.id==='compose'" :x="n.x" :y="n.y+72" text-anchor="middle" class="small">select, combine, retain</text></g>
</svg><div v-if="interactive" class="branch-detail" aria-live="polite">{{selected||'Select a stage. These connections describe the workshop process, not a guaranteed gain.'}}</div><div class="legend"><span>Solid line: version or execution flow</span><span>Dashed line: evidence reviewed</span><span>Color identifies the candidate</span></div></div></template>
<style scoped>svg{width:100%;height:335px}text{font:20px 'IBM Plex Sans';fill:#163c43}.small{font-size:15px}.node[role=button]{cursor:pointer}.node:focus{outline:3px solid #f1ca70}</style>
